"""Public, same-origin consent controls. Account access is independent."""
from html import escape
from .marketing_consent import BRANDS, VERSION, PREFIX, notice

def page(brand,action='',config=None):
    b=config or BRANDS[brand]
    common=f'<a href="/">{escape(b["name"])}</a><h1>Email updates, by choice</h1><p>Optional updates from {escape(b["name"])}. Your account and access to tools do not depend on subscribing.</p>'
    if action in ('confirm','withdraw'):
        word='Confirm subscription'if action=='confirm'else'Unsubscribe'
        body=f'<p>{"Confirm the email permission you chose."if action=="confirm"else"Stop marketing emails from this product. Account and service emails are unaffected."}</p><button id="token-action" data-action="{action}">{word}</button>'
    elif action=='rights':
        body='''<h2>Your marketing consent record</h2><p>This private link expires in 30 minutes. It covers this product’s marketing record only.</p><button id="rights-export">Download my consent record</button><h2>Delete the active marketing record</h2><p>Deletion removes your email address and active marketing profile, cancels queued campaigns and disables this link. A keyed suppression marker and minimal audit remain to prevent accidental marketing reuse.</p><p>This does not delete your product account, purchases, email-provider records or existing backups. Restoring an older active database reapplies the erasure marker. Email already in flight cannot be recalled.</p><label class="choice"><input id="confirm-erasure" type="checkbox"> I want to delete this product’s active marketing record and stop its marketing emails.</label><button id="rights-delete">Delete my marketing record</button>'''
    else:
        if b.get('enabled',True):
            body=f'''<form id="subscribe"><label>Email address<input name="email" type="email" autocomplete="email" maxlength="254" required></label><div class="trap" aria-hidden="true"><label>Company<input name="company" tabindex="-1" autocomplete="off"></label></div><label class="choice"><input name="consent" type="checkbox" required> {escape(notice(brand,b))}</label><input type="hidden" name="notice_version" value="{VERSION}"><button>Send confirmation email</button></form><p>Check your inbox and confirm within 24 hours. This does not subscribe you to other products or tenant sites.</p>'''
        else:
            body='<p>This site is not currently accepting new marketing subscriptions. Existing subscribers can still manage, export or delete their marketing record below.</p>'
        body+='''<details><summary>Manage or stop marketing emails</summary><form id="manage"><label>Email address<input name="email" type="email" autocomplete="email" maxlength="254" required></label><button>Send a preference link</button></form></details><details><summary>Export or delete my consent record</summary><p>We will email a short-lived private link to verify that you own the address.</p><form id="rights-request"><label>Email address<input name="email" type="email" autocomplete="email" maxlength="254" required></label><button>Send my private data link</button></form></details>'''
    return (f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>{escape(b["name"])} email preferences</title><link rel="stylesheet" href="{PREFIX}form.css"><script src="{PREFIX}form.js" defer></script></head><body><main>{common}{body}<p id="status" role="status" aria-live="polite"></p><p id="next"></p><footer><a href="{PREFIX}">Email preferences</a> · <a href="{escape(b["privacy"])}">Privacy information</a> · <a href="mailto:{escape(b["reply_to"])}">Contact us</a><p>{escape(b.get("operator","Atmakosh LLC"))} · Consent records are managed in AgentVire for this site only.</p></footer></main></body></html>').encode()
